  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — maximize total profit (revenue minus raw material cost and processing cost), minimize total cost, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, which constitutes one semantically independent question."
}

